class Solution {
public:
    string minRemoveToMakeValid(string s) {
        // generated by Claude with my direction not to use sort
        vector<int> ps;             // stack of '(' positions
        vector<int> ps_to_remove;   // unmatched ')' positions, ascending
        for (int i = 0; i < (int)s.size(); i++) {
            if (s[i] == '(') {
                ps.push_back(i);
            } else if (s[i] == ')') {
                if (!ps.empty()) ps.pop_back();
                else             ps_to_remove.push_back(i);
            }
        }

        // leftover '(' are all after every unmatched ')', and already ascending
        ps_to_remove.insert(ps_to_remove.end(), ps.begin(), ps.end());

        string out;
        out.reserve(s.size());
        int last_s_pos = 0;
        for (int i : ps_to_remove) {
            out.append(s, last_s_pos, i - last_s_pos);
            last_s_pos = i + 1;
        }
        if (last_s_pos < (int)s.size())
            out.append(s, last_s_pos, string::npos);
        return out;
    }
};